// What waits for this guest's answer (a held room, a cancellation request). The AI's memory keeps the messages,
// not the tool results, so it is told at the start of every turn. A failed lookup just means no note.
const base = $('Reply?').first().json;
const r = $input.first().json || {};
return [{ json: Object.assign({}, base, { pendingNote: r.error ? '' : String(r.note || '') }) }];
